-- Pantry LK — starter content.
-- Paths starting with "/images/" are files bundled in the Next.js /public folder.
-- New uploads from the admin go to the "site-media" storage bucket instead.
--
-- IMPORTANT: projects below are inserted as PUBLISHED with photos_verified = true.
-- Only run this after confirming each photo is a genuine Pantry LK installation
-- and the homeowner agreed to it being shown. Otherwise change them to 'draft'.

begin;

insert into public.site_settings (id, company_name, tagline, phone_display, phone_intl, whatsapp_number, email, kitchen_planner_url, quotation_maker_url, open_apps_in_new_tab, contact_uploads_enabled)
values (1, 'Pantry LK Pvt Ltd', 'Custom kitchen pantries and cabinetry, designed and manufactured in Sri Lanka.', '076 152 8123', '+94761528123', '94761528123', 'pantrylk2026@gmail.com', null, 'https://pantrylk-quotation.netlify.app/', true, false)
on conflict (id) do update set company_name = excluded.company_name, tagline = excluded.tagline, phone_display = excluded.phone_display,
  phone_intl = excluded.phone_intl, whatsapp_number = excluded.whatsapp_number, email = excluded.email, quotation_maker_url = excluded.quotation_maker_url;

insert into public.product_categories (slug, name, description, image_path, image_alt, sort_order) values ('pantry-units', 'Custom pantry units', 'Pull-out and shelved storage sized to your space.', '/images/pantry-pullout.jpg', 'Open tall pantry with pull-out wire storage baskets', 0) on conflict (slug) do nothing;
insert into public.product_categories (slug, name, description, image_path, image_alt, sort_order) values ('base-cabinets', 'Base cabinets', 'Drawers and cupboards that carry the worktop.', '/images/oak-base-units.jpg', 'Oak-finish base cabinets with handleless drawers', 1) on conflict (slug) do nothing;
insert into public.product_categories (slug, name, description, image_path, image_alt, sort_order) values ('wall-cabinets', 'Wall cabinets', 'Solid, glass and open options above the counter.', '/images/glass-wall-units.jpg', 'Black-framed glass wall cabinets above a stone backsplash', 2) on conflict (slug) do nothing;
insert into public.product_categories (slug, name, description, image_path, image_alt, sort_order) values ('tall-pantry-cabinets', 'Tall pantry cabinets', 'Floor-to-ceiling storage and appliance housings.', '/images/white-tall-ovens.jpg', 'White gloss tall units housing a fridge and stacked ovens', 3) on conflict (slug) do nothing;
insert into public.product_categories (slug, name, description, image_path, image_alt, sort_order) values ('drawer-systems', 'Drawer systems', 'Deep drawers and organisers for pots and pans.', null, null, 4) on conflict (slug) do nothing;
insert into public.product_categories (slug, name, description, image_path, image_alt, sort_order) values ('islands-peninsulas', 'Islands & peninsulas', 'A working and gathering point at the centre.', '/images/island-grey-oak-2.jpg', 'Kitchen island with stone-finish top and oak-finish panelling', 5) on conflict (slug) do nothing;

insert into public.products (slug, name, category_id, summary, description, price_mode, finishes, specs, is_featured, status, sort_order, published_at)
select 'tall-pull-out-pantry', 'Tall Pull-Out Pantry', c.id, 'Full-height pull-out baskets, sized to your gap.', 'A full-height pantry with pull-out baskets, so tins, jars and dry goods at the back are as easy to reach as those at the front. Built to the width and height of your space.', 'on_request', '[]'::jsonb, '[{"label":"Dimensions","value":"Made to measure"},{"label":"Internal fittings","value":"Pull-out wire baskets"}]'::jsonb, true, 'published', 0, now()
from public.product_categories c where c.slug = 'pantry-units' on conflict (slug) do nothing;
insert into public.product_images (product_id, path, alt, sort_order) select id, '/images/pantry-pullout.jpg', 'Tall pantry open, showing pull-out wire baskets on each level', 0 from public.products where slug = 'tall-pull-out-pantry' and not exists (select 1 from public.product_images pi join public.products pp on pp.id = pi.product_id where pp.slug = 'tall-pull-out-pantry' and pi.path = '/images/pantry-pullout.jpg');
